INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4201, 'Numbers 26:49', 'Numbers', 26, 49, '&nbsp;يصر او سليم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4202, 'Numbers 26:50', 'Numbers', 26, 50, '&nbsp;په دې قبيلو کښې د سړو شمېر پينځۀ څلوېښت زره او څلور سوه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4203, 'Numbers 26:51', 'Numbers', 26, 51, '&nbsp;ټول اِسرائيليان په شمېر کښې شپږ لاکه يو زر اووۀ سوه او دېرش سړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4204, 'Numbers 26:52', 'Numbers', 26, 52, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4205, 'Numbers 26:53', 'Numbers', 26, 53, '&nbsp;”د ميراث په توګه هغه زمکه په قبيلو باندې د سړو د شمېر په مطابق تقسيم کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4206, 'Numbers 26:57', 'Numbers', 26, 57, '&nbsp;د ليوى اصلى قبيلې دا دى، د جيرسون قبيله، قُهات او مرارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4207, 'Numbers 26:58', 'Numbers', 26, 58, '&nbsp;د هغوئ په اولاد کښې دا وړې قبيلې هم شاملى دى، لِبنى، حبرون، محلى، موشى او قورح. قُهات د عُمرام پلار وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4208, 'Numbers 26:59', 'Numbers', 26, 59, '&nbsp;هغۀ د ليوى لور يوکبد وادۀ کړې وه، چې هغه په مِصر کښې پېدا شوې وه. د هغې نه د عُمرام دوه زامن، هارون او موسىٰ او يوه لور مريم پېدا شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4209, 'Numbers 26:60', 'Numbers', 26, 60, '&nbsp;د هارون دا څلور زامن وُو، ندب، ابيهُو، اِلى‌عزر او اِتمر.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4210, 'Numbers 26:61', 'Numbers', 26, 61, '&nbsp;ندب او ابيهُو په هغه وخت ووژلے شول کله چې هغوئ مالِک خُدائ ته هغه اور پېش کولو کوم چې خُدائ پاک ته قبول نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4211, 'Numbers 26:62', 'Numbers', 26, 62, '&nbsp;د نرانو ليويانو شمېر درويشت زره وو چې د هغوئ عُمر يوه مياشت يا د دې نه زيات وو. هغوئ د نورو بنى اِسرائيلو نه جدا وشمېرلے شول، ځکه چې هغوئ ته د بنى اِسرائيلو په مينځ کښې جائيداد نۀ مِلاوېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4212, 'Numbers 26:63', 'Numbers', 26, 63, '&nbsp;دا ټولې قبيلې موسىٰ او اِلى‌عزر په هغه وخت وشمېرلې چې د اُردن سيند نه پورې يريحو ته مخامخ د موآب په مېدانونو کښې يې د بنى اِسرائيلو مردم‌شمارى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4213, 'Numbers 26:64', 'Numbers', 26, 64, '&nbsp;په دې سړو کښې يو کس هم نۀ وُو چې د سينا په بيابان کښې موسىٰ او هارون په وړومبۍ مردم‌شمارۍ کښې شمېرلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4214, 'Numbers 26:65', 'Numbers', 26, 65, '&nbsp;مالِک خُدائ فرمائيلى وُو چې هغوئ ټول به په صحرا کښې مړۀ شى، نو د يفُنه د زوئ کالب او د نون زوئ يشوَع نه بغېر ټول مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4215, 'Numbers 27:1', 'Numbers', 27, 1, '&nbsp;محلاه، نوعاه، حجلاه، مِلکاه او تِرضاه د صِلافحاد لوڼه وې چې هغه زوئ د حِفر، زوئ د جِلعاد، زوئ د مکير، زوئ د منسى، زوئ د يوسف وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4216, 'Numbers 27:2', 'Numbers', 27, 2, '&nbsp;هغوئ لاړې او د موسىٰ، د اِلى‌عزر اِمام، د مشرانو او د ټول قوم په مخکښې د مالِک خُدائ د حضور د خېمې په خولۀ کښې ودرېدلې او وې وئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4217, 'Numbers 27:3', 'Numbers', 27, 3, '&nbsp;”زمونږ پلار په صحرا کښې مړ شو، د هغۀ زامن نشته، خو هغه د قورح د قبيلې نه نۀ وو، چا چې د مالِک خُدائ خِلاف بغاوت کړے وو، هغه د خپلې ګناه په وجه مړ شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4218, 'Numbers 27:4', 'Numbers', 27, 4, '&nbsp;چې د هغۀ زامن نشته، نو د هغۀ نوم دې ولې د بنى اِسرائيلو نه ختم شى؟ مونږ له هم لکه زمونږ د پلار د خپلوانو په شان جائيداد راکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4219, 'Numbers 27:5', 'Numbers', 27, 5, '&nbsp;نو موسىٰ د هغوئ مسئله مالِک خُدائ ته پېش کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4220, 'Numbers 27:6', 'Numbers', 27, 6, '&nbsp;او مالِک خُدائ هغۀ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4221, 'Numbers 27:7', 'Numbers', 27, 7, '&nbsp;”د صِلافحاد لوڼه ټيک وائى، هغوئ له د هغوئ د پلار د خپلوانو په شان جائيداد ورکړه. او د خپل پلار جائيداد دې هغوئ ته مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4222, 'Numbers 27:8', 'Numbers', 27, 8, '&nbsp;او تۀ خامخا بنى اِسرائيلو ته ووايه چې د کوم سړى زوئ نۀ وى او مړ شى، نو د هغۀ لور ته به جائيداد په ميراث کښې ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4223, 'Numbers 27:9', 'Numbers', 27, 9, '&nbsp;کۀ د هغۀ لوڼه نۀ وى، نو ميراث به يې د وروڼو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4224, 'Numbers 27:10', 'Numbers', 27, 10, '&nbsp;کۀ د هغۀ وروڼه نۀ وى، نو ترونه به يې ميراث اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4225, 'Numbers 27:11', 'Numbers', 27, 11, '&nbsp;کۀ د هغۀ وروڼه يا ترونه هم نۀ وى، نو بيا به د هغۀ نزدې خپلوان د هغۀ ميراث اخلى او دا به د هغوئ د خپل جائيداد په شان وى. اِسرائيليان به دا د قانون په توګه منى، څنګه چې ما، مالِک خُدائ تاسو له حُکم درکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4226, 'Numbers 27:12', 'Numbers', 27, 12, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”د عباريم غرونو ته وخېژه او هغه مُلک ته وګوره کوم چې زۀ بنى اِسرائيلو له ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4227, 'Numbers 27:13', 'Numbers', 27, 13, '&nbsp;کله چې تۀ هغه وګورې، نو د هارون په شان به تۀ هم مړ شې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4228, 'Numbers 27:14', 'Numbers', 27, 14, '&nbsp;ځکه چې تاسو دواړو د صين په صحرا کښې زما د حُکم نه بغاوت کړے وو. کله چې ټول قوم زما خِلاف په مريبه کښې وغورېدو، د هغوئ په مخکښې تاسو زما مقدس طاقت څرګند نۀ کړو.“ مريبه په قادِس کښې د صين په صحرا کښې يوه چينه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4229, 'Numbers 27:15', 'Numbers', 27, 15, '&nbsp;موسىٰ مالِک خُدائ ته سوال وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4230, 'Numbers 27:16', 'Numbers', 27, 16, '&nbsp;”مالِکه خُدايه، تۀ خُدائ پاک يې، هر څيز له ساه ورکوونکے يې، زۀ دا سوال کوم چې يو داسې سړے مقرر کړه چې د دې قوم لار ښودنه کوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4231, 'Numbers 27:17', 'Numbers', 27, 17, '&nbsp;او په جنګ کښې يې مشرى کوى، نو ستا قوم به د داسې ګډو په شان نۀ وى چې شپون يې نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4232, 'Numbers 27:18', 'Numbers', 27, 18, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”د نون زوئ يشوَع بوځه ځکه چې هغه قابل سړے دے او خپل لاسونه د هغۀ په سر کېږده چې ستا ذمه وارۍ ورته حواله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4233, 'Numbers 27:19', 'Numbers', 27, 19, '&nbsp;هغه د اِلى‌عزر اِمام په مخکښې ودروه او د ټول قوم په مخکښې هغۀ له مشرى ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4234, 'Numbers 27:20', 'Numbers', 27, 20, '&nbsp;تۀ هغۀ له څۀ خپل اختيارات هم ورکړه، چې ټول اِسرائيليان د هغۀ تابعدارى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4235, 'Numbers 27:21', 'Numbers', 27, 21, '&nbsp;د فېصلې کولو دپاره به هغه د اِلى‌عزر اِمام نه مشوره اخلى او اِلى‌عزر به اُوريم او تميم زما رضا معلومولو دپاره استعمالوى. نو اِلى‌عزر به د يشوَع او د بنى اِسرائيلو د ټول قوم په هر څيز کښې لار ښودنه کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4236, 'Numbers 27:22', 'Numbers', 27, 22, '&nbsp;موسىٰ هم هغه شان وکړل چې څنګه مالِک خُدائ ورته حُکم کړے وو. هغۀ يشوَع، د اِلى‌عزر اِمام او د ټول قوم په مخکښې ودرولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4237, 'Numbers 27:23', 'Numbers', 27, 23, '&nbsp;چې څنګه مالِک خُدائ حُکم کړے وو، موسىٰ خپل لاسونه د يشوَع په سر کېښودل او خپله مشرى يې ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4238, 'Numbers 28:1', 'Numbers', 28, 1, '&nbsp;مالِک خُدائ موسىٰ ته حُکم وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4239, 'Numbers 28:2', 'Numbers', 28, 2, '&nbsp;”بنى اِسرائيلو له حُکم ورکړه چې خُدائ پاک ته په مقررو وختونو باندې په اور تيارېدونکې نذرانې پېش کوى، د دې خوشبو په مالِک خُدائ ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4240, 'Numbers 28:3', 'Numbers', 28, 3, '&nbsp;دا په اور تيارېدونکې نذرانې دى چې مالِک خُدائ ته پېش کيږى، د هرې ورځې سوزېدونکې نذرانې دپاره، دوه يو کلن ګډُورى چې هيڅ عېب په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4241, 'Numbers 28:4', 'Numbers', 28, 4, '&nbsp;وړومبے ګډُورے په سحر کښې پېش کوئ او دوېم په ماښام کښې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4242, 'Numbers 28:5', 'Numbers', 28, 5, '&nbsp;هر يو به د يو کلو اوړو د غلې نذرانې سره پېش کيږى، چې يو ليټر د زيتُونو ښۀ تېل ورسره ګډ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4243, 'Numbers 28:6', 'Numbers', 28, 6, '&nbsp;دا د هرې ورځې نذرانه ده چې پوره سوزولے شى، کومه چې مخکښې د سينا په غرۀ باندې په اور تيارېدونکې نذرانې په توګه پېش شوې وه، د دې خوشبو په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4244, 'Numbers 28:7', 'Numbers', 28, 7, '&nbsp;د څښلو نذرانې په توګه د وړومبى ګډُورى سره، يو ليټر مے به په قربان‌ګاه باندې تويَولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4245, 'Numbers 28:8', 'Numbers', 28, 8, '&nbsp;په ماښام کښې هغه دوېم ګډُورے پېش کړئ، چې څنګه په سحر کښې پېش شوے وو. دا به د دې د څښلو نذرانې سره پېش کيږى. دا هم يوه په اور تيارېدونکې نذرانه ده، د دې خوشبو په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4246, 'Numbers 28:9', 'Numbers', 28, 9, '&nbsp;د سبت په ورځ دوه يو کلن ګډُورى چې هيڅ عېب په کښې نۀ وى، د غلې نذرانې په توګه دوه کلو اوړۀ چې د زيتُونو تېل ورسره ګډ وى او د څښلو نذرانه پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4247, 'Numbers 28:10', 'Numbers', 28, 10, '&nbsp;دا د هر سبت ورځې سوزېدونکې نذرانه د هرې ورځې د سوزېدونکې او د څښلو نذرانې نه علاوه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4248, 'Numbers 28:11', 'Numbers', 28, 11, '&nbsp;د هرې مياشتې په شروع کښې مالِک خُدائ ته يوه سوزېدونکې نذرانه پېش کوئ، دوه سخى، يو ګډ، اووۀ يو کلن ګډُورى، چې په هر يو کښې هيڅ عېب نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4249, 'Numbers 28:12', 'Numbers', 28, 12, '&nbsp;د غلې نذرانې په توګه، اوړۀ پېش کړئ چې د زيتُونو تېل ورسره ګډ وى، د هر يو سخى سره درې کلو اوړۀ، دوه کلو د ګډ سره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4250, 'Numbers 28:13', 'Numbers', 28, 13, '&nbsp;او يو کلو د هر يو ګډُورى سره. دا سوزېدونکې نذرانې په اور تيارېدونکې نذرانې دى، د دې خوشبو په مالِک خُدائ ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4251, 'Numbers 28:14', 'Numbers', 28, 14, '&nbsp;د څښلو صحيح نذرانه د هر يو سخى سره دوه ليټره مے دى، يو نيم ليټر به د ګډ سره وى او يو ليټر به د هر يو ګډُورى سره وى. دا اصُول د سوزېدونکې نذرانې دپاره د ټول کال د هرې مياشتې د وړومبۍ ورځې دپاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4252, 'Numbers 28:15', 'Numbers', 28, 15, '&nbsp;او يو چېلے د ګناه د نذرانې په توګه مالِک خُدائ ته پېش کړئ، دا به د هرې ورځې د سوزېدونکې نذرانې او د څښلو د نذرانې نه به علاوه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4253, 'Numbers 28:16', 'Numbers', 28, 16, '&nbsp;د وړومبۍ مياشتې په څوارلسمه ورځ به د مالِک خُدائ په درناوى کښې د فسحې اختر کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4254, 'Numbers 28:17', 'Numbers', 28, 17, '&nbsp;د دې مياشتې په پينځلسمه ورځ به اختر شروع کيږى چې اووۀ ورځې به وى، چې په دې دوران کښې به صِرف پتيره روټۍ خوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4255, 'Numbers 28:18', 'Numbers', 28, 18, '&nbsp;د اختر په وړومبۍ ورځ به تاسو د عبادت دپاره راغونډېږئ او هيڅ کار به نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4256, 'Numbers 28:19', 'Numbers', 28, 19, '&nbsp;په اور تيارېدونکې نذرانې په توګه مالِک خُدائ ته يوه سوزېدونکې نذرانه پېش کوئ يعنې دوه سخى، يو ګډ او اووۀ يو کلن ګډُورى، چې په دې کښې هم څۀ عېب نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4257, 'Numbers 28:20', 'Numbers', 28, 20, '&nbsp;د غلې صحيح نذرانه پېش کوئ چې په هغه اوړو کښې د زيتُونو تېل ګډ وى، درې کلو د هر يو سخى سره، دوه کلو د ګډ سره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4258, 'Numbers 28:21', 'Numbers', 28, 21, '&nbsp;او يو کلو د هر يو ګډُورى سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4259, 'Numbers 28:22', 'Numbers', 28, 22, '&nbsp;د ګناه نذرانې په توګه يو چېلے هم پېش کوئ، چې د خلقو کفاره ادا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4260, 'Numbers 28:23', 'Numbers', 28, 23, '&nbsp;دا ټولې نذرانې د هر سحر د سوزېدونکې نذرانې نه علاوه پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4261, 'Numbers 28:24', 'Numbers', 28, 24, '&nbsp;هم دغه شان، اووۀ ورځې مالِک خُدائ ته په اور تيارېدونکې نذرانې پېش کوئ، دا خوشبو په هغۀ باندې ښۀ لګى. دا د هرې ورځې سوزېدونکې نذرانې او د څښلو نذرانې نه علاوه پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4262, 'Numbers 28:25', 'Numbers', 28, 25, '&nbsp;په اوومه ورځ د عبادت دپاره رايوځائ کېږئ او کار مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4263, 'Numbers 28:26', 'Numbers', 28, 26, '&nbsp;د لَو کولو اختر په وړومبۍ ورځ، کله چې تاسو د نوې غلې نذرانه مالِک خُدائ ته پېش کوئ، نو تاسو به د عبادت دپاره راجمع کېږئ او هيڅ کار به نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4264, 'Numbers 28:27', 'Numbers', 28, 27, '&nbsp;يوه سوزېدونکې نذرانه پېش کوئ چې د هغې خوشبو په مالِک خُدائ باندې ښۀ لګى يعنې دوه سخى، يو ګډ او اووۀ يو کلن ګډُورى، چې هيڅ عېب په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4265, 'Numbers 28:28', 'Numbers', 28, 28, '&nbsp;د غلې صحيح نذرانه پېش کوئ چې په اوړو کښې يې د زيتُونو تېل ګډ وى يعنې درې کلو د هر يو سخى سره، دوه کلو د ګډ سره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4266, 'Numbers 28:29', 'Numbers', 28, 29, '&nbsp;او يو کلو د هر يو ګډُورى سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4267, 'Numbers 28:30', 'Numbers', 28, 30, '&nbsp;د ګناه نذرانې په توګه يو چېلے هم پېش کوئ، چې ستاسو د خلقو کفاره ادا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4268, 'Numbers 28:31', 'Numbers', 28, 31, '&nbsp;د هرې ورځې د سوزېدونکې نذرانې او د غلې د نذرانې نه علاوه به تاسو دا نذرانې او د څښلو نذرانه پېش کوئ. او ياد ساتئ چې دا ځناور بې‌عېبه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4269, 'Numbers 29:1', 'Numbers', 29, 1, '&nbsp;د اوومې مياشتې په وړومبۍ ورځ به تاسو د عبادت دپاره راغونډېږئ او په دې ورځ به هيڅ کار نۀ کيږى. په هغه ورځ به بيګل وغږيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4270, 'Numbers 29:2', 'Numbers', 29, 2, '&nbsp;مالِک خُدائ ته يو سوزېدونکې نذرانه پېش کړئ، د دې خوشبو په مالِک خُدائ باندې ښۀ لګى، يو سخے، يو ګډ، اووۀ يو کلن ګډُورى، چې په يو کښې هم هيڅ عېب نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4271, 'Numbers 29:3', 'Numbers', 29, 3, '&nbsp;د اوړو صحيح نذرانه پېش کوئ چې د زيتُونو تېل ورسره ګډ وى يعنې درې کلو د سخى سره او دوه کلو د ګډ سره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4272, 'Numbers 29:4', 'Numbers', 29, 4, '&nbsp;او يو کلو د هر يو ګډُورى سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4273, 'Numbers 29:5', 'Numbers', 29, 5, '&nbsp;د ګناه نذرانې په توګه يو چېلے هم پېش کوئ نو په دې سره د خپل ځان کفاره ادا کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4274, 'Numbers 29:6', 'Numbers', 29, 6, '&nbsp;او دا نذرانې د مياشتې د وړومبۍ ورځې او د هرې ورځې د سوزېدونکې نذرانې او د غلې نذرانې نه علاوه پېش کوئ، او د هرې ورځې سوزېدونکې نذرانه ورسره د دې د غلې نذرانه او د څښلو نذرانه. په اور تيارېدونکې د دې نذرانو خوشبو په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4275, 'Numbers 29:7', 'Numbers', 29, 7, '&nbsp;د اوومې مياشتې په لسمه ورځ د عبادت دپاره راغونډېږئ، هيڅ څيز به نۀ خورئ او نۀ به څۀ کار کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4276, 'Numbers 29:8', 'Numbers', 29, 8, '&nbsp;مالِک خُدائ ته يوه سوزېدونکې نذرانه پېش کوئ، د دې خوشبو په هغۀ باندې ښۀ لګى، يو سخے، يو ګډ، اووۀ يو کلن ګډُورى، چې په يو کښې هم هيڅ عېب نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4277, 'Numbers 29:9', 'Numbers', 29, 9, '&nbsp;د غلې دانې صحيح نذرانه پېش کوئ چې په اوړو کښې د زيتُونو تېل ورسره ګډ وى، درې کلو اوړۀ د سخى سره، دوه کلو د ګډ سره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
