(4292, 'Numbers 29:36', 'Numbers', 29, 36, '&nbsp;په اور تيارېدونکې نذرانې په توګه يوه سوزېدونکې نذرانه مالِک خُدائ ته پېش کړئ، د دې خوشبو په هغۀ باندې ښۀ لګى، يو سخے، يو ګډ، اووۀ يو کلن ګډُورى، چې په يو کښې هم هيڅ عېب نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4293, 'Numbers 29:39', 'Numbers', 29, 39, '&nbsp;دا اصُول د سوزېدونکې نذرانې، د غلې دانې نذرانې، د څښلو نذرانې او د سلامتۍ نذرانې دپاره دى چې تاسو يې مالِک خُدائ ته په خپلو مقررو اخترونو کښې پېش کوئ. دا د هغه نذرانو نه علاوه دى چې تاسو يې د يوې منښتې د پوره کېدو د نذرانو يا د رضاکارانه نذرانو په توګه ورکوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4294, 'Numbers 29:40', 'Numbers', 29, 40, '&nbsp;نو موسىٰ بنى اِسرائيلو ته هغه هر څۀ وفرمائيل چې مالِک خُدائ هغۀ ته د څۀ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4295, 'Numbers 30:1', 'Numbers', 30, 1, '&nbsp;موسىٰ د بنى اِسرائيلو د قبيلو مشرانو ته دا اصُول وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4296, 'Numbers 30:2', 'Numbers', 30, 2, '&nbsp;کله چې يو سړے مالِک خُدائ ته د منښتې په توګه څۀ څيز ومنى يا سخت قسم وخورى، نو هغه به خپله وعده نۀ ماتوى او خامخا به يې پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4297, 'Numbers 30:3', 'Numbers', 30, 3, '&nbsp;کله چې يوه جينۍ د پلار په کور کښې اوسيږى او منښته ومنى چې يو څيز به مالِک خُدائ له ورکوى يا د څۀ څيز نه د ځان ساتلو وعده وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4298, 'Numbers 30:4', 'Numbers', 30, 4, '&nbsp;هغه به خامخا هغه هر څۀ کوى چې هغې کومه منښته منلې وى يا يې وعده کړې وى خو کۀ د هغې پلار ترې نه خبر شى او څۀ اِعتراض وکړى نو بيا به يې نۀ پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4299, 'Numbers 30:5', 'Numbers', 30, 5, '&nbsp;خو چې کله يې پلار خبر شى او کۀ ورته ووائى چې دا وعده مۀ پوره کوه، نو د هغې دپاره ضرورى نۀ ده چې دا وعده پوره کړى. مالِک خُدائ به هغه معاف کړى، ځکه چې پلار يې د دې د پوره کولو نه منع کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4300, 'Numbers 30:6', 'Numbers', 30, 6, '&nbsp;کۀ يوه ناوادۀ شوې ښځه يوه منښته ومنى، قصداً يا په بې‌خيالۍ کښې، يا وعده وکړى چې د څۀ څيز نه به ځان ساتى او بيا وادۀ شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');